<?php
declare(strict_types=1);
$cfg=__DIR__.'/auth_config.php';$lock=__DIR__.'/.dashboard_installed';
if(is_file($cfg)&&is_file($lock)&&!isset($_GET['force'])){header('Location: librenms.php');exit;}
$error='';$done=false;function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function ident($v){return preg_match('/^[A-Za-z0-9_]{1,48}$/',$v);}
if($_SERVER['REQUEST_METHOD']==='POST')try{
 $host=trim($_POST['host']??'127.0.0.1');$port=(int)($_POST['port']??3306);$root=trim($_POST['root_user']??'root');$rootPass=$_POST['root_pass']??'';
 $db=trim($_POST['db_name']??'librenms_dashboard');$app=trim($_POST['app_user']??'dashboard_app');$appPass=$_POST['app_pass']??'';
 $admin=strtolower(trim($_POST['admin_user']??'admin'));$name=trim($_POST['admin_name']??'Super Administrator');$adminPass=$_POST['admin_pass']??'';
 if(!ident($db)||!ident($app))throw new RuntimeException('Nama database dan user DB hanya boleh huruf, angka, underscore.');
 if(!preg_match('/^[a-z0-9._-]{3,50}$/',$admin))throw new RuntimeException('Username Admin tidak valid.');
 if(strlen($appPass)<12||strlen($adminPass)<8)throw new RuntimeException('Password DB minimal 12 karakter dan password Admin minimal 8 karakter.');
 $pdo=new PDO("mysql:host=$host;port=$port;charset=utf8mb4",$root,$rootPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$q=fn($v)=>$pdo->quote($v);
 $pdo->exec("CREATE DATABASE IF NOT EXISTS `$db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");
 foreach(['localhost','127.0.0.1'] as $ah){$pdo->exec("CREATE USER IF NOT EXISTS `$app`@".$q($ah)." IDENTIFIED BY ".$q($appPass));$pdo->exec("ALTER USER `$app`@".$q($ah)." IDENTIFIED BY ".$q($appPass));$pdo->exec("GRANT SELECT,INSERT,UPDATE,DELETE ON `$db`.* TO `$app`@".$q($ah));}
 $pdo->exec("USE `$db`");$pdo->exec("CREATE TABLE IF NOT EXISTS dashboard_users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL DEFAULT '',role ENUM('admin','viewer') NOT NULL DEFAULT 'viewer',is_active TINYINT(1) NOT NULL DEFAULT 1,last_login DATETIME NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY(role,is_active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $st=$pdo->prepare("INSERT INTO dashboard_users(username,password_hash,full_name,role,is_active) VALUES(?,?,?,'admin',1) ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash),full_name=VALUES(full_name),role='admin',is_active=1");$st->execute([$admin,password_hash($adminPass,PASSWORD_DEFAULT),$name?:$admin]);
 $data=['host'=>$host,'port'=>$port,'database'=>$db,'username'=>$app,'password'=>$appPass];if(file_put_contents($cfg,"<?php\nreturn ".var_export($data,true).";\n",LOCK_EX)===false)throw new RuntimeException('Folder tidak writable.');@chmod($cfg,0640);file_put_contents($lock,date('c'));@chmod($lock,0640);$done=true;
}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setup Dashboard</title><style>*{box-sizing:border-box}body{margin:0;padding:25px;min-height:100vh;font:14px Arial;color:#18384b;background:linear-gradient(135deg,#061722,#0b4257)}main{max-width:850px;margin:auto;border-radius:20px;overflow:hidden;background:#f7fbfd;box-shadow:0 25px 70px #0008}header{padding:25px 30px;color:#fff;background:linear-gradient(120deg,#08364b,#0b8191,#2d70d7)}section{padding:25px 30px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}fieldset{border:1px solid #d2e3eb;border-radius:12px;padding:16px}legend,label{font-size:11px;font-weight:bold}input{width:100%;height:42px;margin:6px 0 12px;padding:0 10px;border:1px solid #bfd4df;border-radius:8px}button,a.go{display:block;width:100%;padding:14px;border:0;border-radius:9px;text-align:center;text-decoration:none;color:#fff;font-weight:bold;background:linear-gradient(135deg,#176fd2,#2d8cff,#0aa6b8)}.msg{padding:12px;margin-bottom:15px;border-radius:9px;background:#e8f5ff}.err{color:#a72638;background:#fff0f2}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><main><header><h1>First-Time Setup Wizard</h1><p>Database login dan akun Admin dibuat otomatis tanpa import SQL.</p></header><section><?php if($done):?><h2>Setup berhasil</h2><p>Database, tabel, user aplikasi, dan Admin pertama sudah dibuat.</p><a class="go" href="librenms.php">Buka Login Dashboard</a><?php else:?><?php if($error):?><div class="msg err"><?=h($error)?></div><?php else:?><div class="msg">Isi akun MySQL yang punya izin CREATE DATABASE, CREATE USER, GRANT, dan CREATE TABLE. Password MySQL Admin tidak disimpan.</div><?php endif;?><form method="post"><div class="grid"><fieldset><legend>MYSQL ADMIN</legend><label>Host<input name="host" value="<?=h($_POST['host']??'127.0.0.1')?>"></label><label>Port<input name="port" type="number" value="<?=h($_POST['port']??3306)?>"></label><label>User<input name="root_user" value="<?=h($_POST['root_user']??'root')?>"></label><label>Password<input name="root_pass" type="password"></label></fieldset><fieldset><legend>DATABASE BARU</legend><label>Database<input name="db_name" value="<?=h($_POST['db_name']??'librenms_dashboard')?>"></label><label>App DB User<input name="app_user" value="<?=h($_POST['app_user']??'dashboard_app')?>"></label><label>App DB Password<input name="app_pass" type="password" minlength="12" required></label></fieldset><fieldset><legend>ADMIN PERTAMA</legend><label>Username<input name="admin_user" value="<?=h($_POST['admin_user']??'admin')?>"></label><label>Nama<input name="admin_name" value="<?=h($_POST['admin_name']??'Super Administrator')?>"></label><label>Password<input name="admin_pass" type="password" minlength="8" required></label></fieldset></div><button>Create Database & Start Dashboard</button></form><?php endif;?></section></main></body></html>
